INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('clockwork-virus','Clockwork Virus','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"clockwork-virus","name":"Clockwork Virus","team":"minion","ability":"This spreads by choosing. If all living are infected, all learn this & evil must die today, or evil wins. [+1 Outsider with this]","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Clockwork Virus (SCP-217) is an incurable and persistent virus that converts organic tissue into clockwork parts. Late-stage victims suffer from mental deterioration.","summaryBullets":["The Clockwork Virus isn''t a Minion player, and is instead a virus that originates from an Outsider - this change happens during setup.","At any time, when a player chooses to use their ability on an infected player, or vice-versa, that uninfected player becomes infected. The plague spreads by touch, and is mostly incurable. The same also applies during the day, when a player nominates an infected player, or vice-versa.","At dawn, if all living players are infected, all players know the Clockwork Virus has infected the entire populous.","From then on, when night falls, if no evil player died today, evil wins. Exiling an evil Traveller does count."],"howToRun":["While setting up the game, before putting character tokens in the bag, add one extra Outsider character token and remove the Clockwork Virus''s character token {{i|(or lack thereof)}}, then put the **INFECTED** reminder token in the center of the Grimoire.","While preparing the first night, move the Clockwork Virus''s **INFECTED** reminder token from the center of the Grimoire by any Outsider''s character token.","At any time, if a player chooses to use their ability on or nominates a player with **INFECTED** reminder token, and they aren''t marked with it themselves, that player is **infected with the Clockwork Virus** - mark them with the Clockwork Virus''s **INFECTED** reminder. Similarly, if a player marked with the **INFECTED** reminder token chooses to use their ability on or nominates a player that isn''t marked with it, the chosen player is **infected with the Clockwork Virus** - mark them with the Clockwork Virus''s **INFECTED** reminder.","Immediately after dawn, if all living players are marked with the Clockwork Virus''s **INFECTED** reminder token, put the Clockwork Virus''s **COUNTDOWN** reminder token in the center of the Grimoire, declare that all living players are infected with the Clockwork Virus, and that from now on, if an evil player is not killed each day, the evil team automatically wins.","Each dusk, if no evil player was killed today and the Clockwork Virus''s **COUNTDOWN** is in the center of the Grimoire, the game ends and evil wins."],"quote":"loneliness + alienation + fear = clockwork. clockwork + despair + self-worth ÷ mockery = clockwork. clockwork ÷ condemnation ÷ misunderstanding ⋅ guilt = clockwork. clockwork ⋅ shame ⋅ failure ⋅ judgment n=y where y=hope and n=folly, love=lies, life=death, self=clockwork","iconBy":"le_nuberto","jinxes":[{"name":"Barber","align":"good","text":"When the Barber ability activates, the Demon may choose to not actually swap the characters of the players they pick, only transmitting the infection.","id":"barber"},{"name":"Engineer","align":"good","text":"If the Engineer swaps out the Clockwork Virus, a living player becomes a Minion & learns the evil team, prioritizing an Outsider. The Engineer cannot swap in the Clockwork Virus.","id":"engineer"},{"name":"Hatter","align":"good","text":"If the Demon chooses to swap out the Clockwork Virus using the Hatter''s ability, a living player becomes a evil Minion & learns the evil team, prioritizing an Outsider. The Demon cannot swap in the Clockwork Virus using the Hatter''s ability.","id":"hatter"},{"name":"Kazali","align":"evil","text":"If the Kazali wants the Clockwork Virus in-play, they must have it as their first choice. If they do choose for the Clockwork Virus, 1 good player (prioritizing Outsider) is infected and the Kazali knows who they are.","id":"kazali"},{"name":"Pit-Hag","align":"evil","text":"If the Pit-Hag chooses a good player with the Clockwork Virus, they instead infect that player with the Clockwork Virus if they already aren''t infected (this doesn''t infect the Pit-Hag).","id":"pithag"},{"name":"Preacher","align":"good","text":"If the Preacher chooses an infected player, they become infected but the chosen player becomes uninfected.","id":"preacher"}],"firstNight":0,"otherNight":93.217,"remindersGlobal":["Infected","Infected","Infected","Infected","Infected","Infected","Infected","Infected","Infected","Infected","Infected","Infected","Infected","Infected","Infected","Countdown"],"setup":true,"special":[{"name":"bag-disabled","type":"selection"}],"otherNightReminder":"If all good players are infected with the Clockwork Virus: Announce this, and that from now on, an evil player must be killed each day, or the evil team wins.","art":"art/clockwork-virus.png","jsonId":"clockworkvirus_scp_fragmented_veil","curata":false}','scp-fragmented-veil/clockwork-virus','published',datetime('now'),datetime('now')),
('god','"God"','minion','legitch, le_nuberto',NULL,'','SCP Fragmented Veil','{"slug":"god","name":"\"God\"","team":"minion","ability":"Whomever threatens to reach the Demon''s identity might have something bad happen to them (max 1 poison/misinfo).","creator":"legitch, le_nuberto","appearsIn":"SCP Fragmented Veil","lede":"\"God\" (SCP-343) is a powerful reality bender that claims to be God, but **[ERROR: DATA LOSS]**...cannot be trusted...**[ERROR: DATA LOSS]**...danger to us all.","summaryBullets":["\"God\" performs wicked acts against those who get closer to the truth.","Anyone who can reasonably threaten reaching the Demon''s identity can be a target.","This includes anyone suspecting the Demon to be evil, voicing their thoughts on them being evil, or has an ability that threatens identifying them.","Anything negative can happen to a victim provided it is exclusive to them, including Poisoning, forced into Madness, transformed into an Outsider, misregistering as evil, or even dieing at any time.","However, only 1 infliction poisoning or false information on that cursed player can occur throughout the entire game with this ability {{i|(albeit it can last indefinitely and does not conflict with them possibly misregistering falsely)}}.","Additionally, the effects of the \"Something bad\" can bypass protections against it, such as death versus a Tea-Lady protected player."],"howToRun":["At any time, if any player threatens to reach the Demon''s identity, whether socially or through their ability, you may choose to mark them with one of \"God\"''s supporting reminder tokens - **EARTH, WIND, AIR, FIRE**, to remind you that they are now mad, will become an Outsider tonight, will die, will misregister as evil, or simply as a reminder to decide on what to do later. However, this cannot **poison** or force false info onto said threatening player unless you use the **UNHOLY** reminder token, which you can only place once."],"tips":["Remember, every effect besides poisoning or false info will have some lead/trail to it that might then be used to uncover who the Demon is. Be wary about how often you perform these miraculous acts of God, but also don''t let that make you afraid to then doing too little with this character."],"quote":"I am the way and the truth and the life. No one comes to the Father except through me. I wish for all of my children to p̶r̶o̶s̶p̶e̶r DIE. For the light of my will to grant them l̶i̶f̶e DEATH. I hope they are all well off i̶n̶ ̶t̶r̶a̶n̶q̶u̶i̶l̶i̶t̶y DEAD, and a happy  r̶e̶j̶u̶v̶e̶n̶a̶t̶i̶o̶n̶ ̶o̶f̶ ̶t̶h̶e̶ ̶m̶i̶n̶d̶ ̶&̶ ̶s̶o̶u̶l HOPE YOU''RE DYING.","iconBy":"le_nuberto","customBoxes":[{"title":"In the almanac JSON","content":"**Ability:** Whomever threatens to reach the Demon''s identity might have something bad happen to them (max 1 poisoning/misinfo).\n**Reminders:** Unholy, Water, Earth, Fire, Air"},{"title":"Alternative JSON & How to Run (Older)","content":"For if you want a more contained \"God\" that is easier to track for all players involved, use this JSON to contain the negative effects to only 3 players, but they are not constrained by the 1 misinfo/poisoning limit.\n\nAt any time, if any player threatens to reach the Demon''s identity, whether socially or through their ability, you may choose to mark them with one of \"God\"''s SOMETHING BAD reminder tokens - to remind you that they are now mad, will become an Outsider tonight, will die, will misregister as evil, or simply as a reminder to decide on what to do later.\n\n**\"God\" █~** (Minion)\nThrice per game, whomever threatens to reach the Demon''s identity might have something bad happen to them.\n\n**Reminders:** Something bad, Something bad, Something bad\n**Credit:** Ability: @legitch & @le_nuberto. Image: @le_nuberto"}],"firstNight":0,"otherNight":0,"reminders":["Poisoned","Water","Earth","Fire","Air"],"setup":false,"art":"art/god.png","jsonId":"god_scp_fragmented_veil","curata":false}','scp-fragmented-veil/god','published',datetime('now'),datetime('now')),
('caruncula','Caruncula','minion','legitch',NULL,'','SCP Fragmented Veil','{"slug":"caruncula","name":"Caruncula","team":"minion","ability":"Your Townsfolk neighbours are poisoned & if you are chosen by an ability, they might instead. [You are the farthest from evil]","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Caruncula (SCP-372) is a stalking quadruped always in the corner of your eye, away from the action between good and evil.","summaryBullets":["The Caruncula will replace the character of the player furthest away from evil players in the number of steps.","The replacement acts at a time that is technically both during setup and during the first night.","The Caruncula player will still have been their original character when tokens were distributed, thus they have a free bluff.","The Caruncula''s closest clockwise and counterclockwise Townsfolk neighbours are poisoned, regardless of whether they are alive or dead. If Caruncula dies or otherwise loses their ability, then those two players become healthy.","Lastly, if any ability happens to choose the Caruncula, it might be redirected onto one of the neighbours."],"howToRun":["While setting up the game, before putting the character tokens in the bag, remove the Caruncula''s character token and add one Townsfolk character token.","While preparing the first night, identify the player furthest away from any evil player in either direction {{i|(if there are multiple people with the furthest direction away, it is recommended you prioritize identifying a Townsfolk over an Outsider, although it is up to your choice)}}. Replace their old character token with the Caruncula''s token, show them the “You Are” info token then the Caruncula''s character token, and give a thumbs down. Additionally, the Townsfolk neighbours of the Caruncula become **poisoned** - mark them with **POISONED** reminders.","If the Caruncula turns into a different character, or if a new player becomes the Caruncula, the new neighbours of the Caruncula become **poisoned**, and the old neighbours become **healthy** - move the Caruncula’s **POISONED** reminders immediately if needed.","Each time the Caruncula would be chosen by any ability - you may choose to have it instead be redirected to one of their Townsfolk neighbours instead."],"tips":["The original character that the Caruncula was should not one of the available given bluffs to the Demon, for not letting that aspect of the Caruncula''s ability go to waste."],"quote":"I just saw it- there! Look, I just... swear I... saw... nevermind. It was only a false alarm, all derived from my own lack of sleep- THERE IT IS AGAIN!","iconBy":"le_nuberto","jinxes":[{"name":"Bounty Hunter","align":"good","text":"An evil Townsfolk is only created if the Bounty Hunter is still in play after the Caruncula comes into play.","id":"bountyhunter"},{"name":"Butler","align":"good","text":"The Butler cannot have their ability misdirected by the Caruncula.","id":"butler"},{"name":"Choirboy","align":"good","text":"The Caruncula will instead be a player adjecent to the King if the King is the only player farthest from evil.","id":"choirboy"},{"name":"Huntsman","align":"good","text":"If the Caruncula comes into play from the Damsel, and a Huntsman is in play, a good player becomes the Damsel.","id":"huntsman"},{"name":"Kazali","align":"evil","text":"If the Kazali wants the Caruncula in-play, they must have it as their last choice. If they do choose for the Caruncula, the Storyteller chooses who it is.","id":"kazali"},{"name":"Lord of Typhon","align":"evil","text":"The Caruncula is the player farthest away from the Lord of Typhon, despite their setup ability.","id":"lordoftyphon"},{"name":"Ogre","align":"good","text":"The Ogre cannot have their ability misdirected by the Caruncula.","id":"ogre"},{"name":"Plague Doctor","align":"good","text":"If the Plague Doctor dies, a living Minion (prioritizing the one farthest away from other evil players) gains the Caruncula''s ability in addition to their own ability, and learns this.","id":"plaguedoctor"},{"name":"Vigormortis","align":"evil","text":"If the Vigormortis kills the Caruncula, they additionally poison a Townsfolk neighbouring one of their currently poisoned Townsfolk.","id":"vigormortis"},{"name":"Antipath","align":"evil","text":"The Antipath registers as good to the Caruncula in it''s setup effect. If the Caruncula would replace the Antipath, 1 good player becomes the evil Antipath.","slug":"antipath"},{"name":"Obscrul","align":"evil","text":"The Caruncula will instead be a player adjecent to the Archivist if the Archivist is the only player farthest from evil.","id":"obscrul_the_bootleggers_anthology"}],"customBoxes":[{"title":"Alternative JSON (Older)","content":"For if you want to contain what the Caruncula is allowed to deflect to just deaths for simpler (albiet more limiting for the Caruncula) gameplay, use this JSON.\n\n**Caruncula █-** (Minion)\nYour Townsfolk neighbours are poisoned & if you die, they might instead. [You are the farthest from evil]\n\n**First night:** Wake the player whose token was changed to the Caruncula in the Grim, show them the ''You Are'' card, the Caruncula, and a thumbs down.\n**Reminders:** Poisoned, Poisoned\n**Setup:** yes\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nBounty Hunter: An evil Townsfolk is only created if the Bounty Hunter is still in play after the Caruncula comes into play.\nChoirboy: The Caruncula will instead be a player adjecent to the King if the King is the only player farthest from evil.\nHuntsman: If the Caruncula comes into play from the Damsel, and a Huntsman is in play, a good player becomes the Damsel.\nKazali: If the Kazali wants the Caruncula in-play, they must have it as their last choice. If they do choose for the Caruncula, the Storyteller chooses who it is.\nLord of Typhon: The Caruncula is the player farthest away from the Lord of Typhon, despite their setup ability.\nPlague Doctor: If the Plague Doctor dies, a living Minion (prioritizing the one farthest away from other evil players) gains the Caruncula''s ability in addition to their own ability, and learns this.\nVigormortis: If the Vigormortis kills the Caruncula, they additionally poison a Townsfolk neighbouring one of their currently poisoned Townsfolk.\nAntipath: The Antipath registers as good to the Caruncula in it''s setup effect. If the Caruncula would replace the Antipath, 1 good player becomes the evil Antipath.\nObscrul: The Caruncula will instead be a player adjecent to the Archivist if the Archivist is the only player farthest from evil."}],"firstNight":0.0372,"otherNight":0,"reminders":["Poisoned","Poisoned"],"setup":true,"special":[{"name":"bag-disabled","type":"selection"}],"firstNightReminder":"Wake the player whose token was changed to the Caruncula in the Grim, show them the ''You Are'' card, the Caruncula, and a thumbs down.","art":"art/caruncula.png","jsonId":"caruncula_scp_fragmented_veil","curata":false}','scp-fragmented-veil/caruncula','published',datetime('now'),datetime('now'));
